-- Demo places with no owner (pagodas, parks...) from frontend/src/data/places.js.
-- Places 20+ are made-up shops that need owner users, so they are left out here.
SET NAMES utf8mb4;
USE pointer_db;
ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), name = VALUES(name), description = VALUES(description),
  phone = VALUES(phone), open_hours = VALUES(open_hours), address = VALUES(address), lat = VALUES(lat), lng = VALUES(lng);
